class Main {
    // 전달받은 숫자로 새 배송비를 계산해요.
    static int next_fee(int fee) {
        return fee + 1000;
    }

    public static void main(String[] args) {
        // 호출에서 넘기는 값과 반환 결과를 연결해요.
        int fee = 2000;
        System.out.println(next_fee(fee));
    }
}

class Main {
    // amount는 전달된 숫자를 복사해서 받아요.
    static void show_next(int amount) {
        amount = amount + 1000;
        System.out.println(amount);
    }

    public static void main(String[] args) {
        // 안에서 바뀐 숫자와 밖의 숫자를 따로 봐요.
        int amount = 2000;
        show_next(amount);
        System.out.println(amount);
    }
}

class Main {
    // 전달받은 숫자로 새 배송비를 계산해요.
    static int next_fee(int fee) {
        return fee + 1000;
    }

    public static void main(String[] args) {
        // 반환받은 숫자를 아직 저장하지 않아요.
        int amount = 2000;
        next_fee(amount);
        System.out.println(amount);
    }
}

class Main {
    // 첫 값은 가격, 둘째 값은 수량이에요.
    static int discounted(int price, int quantity) {
        return price - quantity * 100;
    }

    public static void main(String[] args) {
        // 같은 int여도 자리의 의미는 달라요.
        int price = 3000;
        int quantity = 2;
        System.out.println(discounted(price, quantity));
    }
}

class Main {
    // 기준에 닿으면 현재 메서드에서 바로 돌아가요.
    static int shipping(int amount) {
        if (amount >= 10000) {
            return 0;
        }
        // 위에서 돌아가지 않은 주문만 여기까지 와요.
        return 2500;
    }

    public static void main(String[] args) {
        // 돌아온 배송비를 main에서 출력해요.
        int amount = 10000;
        System.out.println(shipping(amount));
    }
}

class Main {
    // 정수 인수는 정수 나눗셈을 써요.
    static int half(int amount) {
        return amount / 2;
    }
    // 실수 인수는 다른 매개변수 타입의 선언을 골라요.
    static double half(double amount) {
        return amount / 2;
    }

    public static void main(String[] args) {
        // 같은 숫자라도 호출에서 전달한 타입이 달라요.
        System.out.println(half(5));
        System.out.println(half(5.0));
    }
}

class Main {
    // 합을 저장하고 모든 원소를 읽은 뒤 돌려줘요.
    static int total(int[] prices) {
        int result = 0;
        for (int price : prices) {
            result = result + price;
        }
        return result;
    }

    public static void main(String[] args) {
        // 같은 주문의 두 가격을 메서드에 넘겨요.
        int[] prices = {2000, 3000};
        System.out.println(total(prices));
    }
}

